from typing import Annotated
from fastapi import FastAPI, Depends, Response
from fastapi.dependencies.utils import analyze_param
import inspect

def modify_response():
    return Response(content="modified")

def test_response_dependency():
    try:
        analyze_param(
            param_name="response",
            annotation=Annotated[Response, Depends(modify_response)],
            value=inspect.Signature.empty,
            is_path_param=False
        )
        print("Success")
    except AssertionError as e:
        print(f"AssertionError: {e}")
    except Exception as e:
        print(f"Exception: {e}")

test_response_dependency()
